using System.Net.Http.Headers;
using Microsoft.EntityFrameworkCore;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json.Nodes;
using Microsoft.AspNetCore.DataProtection;
namespace Society.Api;
public record DispatchResult(string Status,string? ProviderId=null,string? Error=null,bool Retryable=false,decimal? Cost=null,string? Currency=null);
public interface ICommunicationProvider {Task<DispatchResult> Send(Outbox job,CommunicationAccount account,JsonObject secrets,CancellationToken cancel);Task<bool> Verify(CommunicationAccount account,JsonObject secrets,CancellationToken cancel);}
public class CommunicationProviders(IHttpClientFactory factory,IDataProtectionProvider protection,IConfiguration config,IHostEnvironment env,AppDb db,IObjectStore store):ICommunicationProvider {
 public string Protect(string value)=>protection.CreateProtector("assemblia.communications.accounts.v1").Protect(value);
 public JsonObject Secrets(CommunicationAccount account)=>string.IsNullOrEmpty(account.ProtectedSecrets)?new():MembershipService.Json(protection.CreateProtector("assemblia.communications.accounts.v1").Unprotect(account.ProtectedSecrets));
 public static bool Fixed(string a,string b)=>CryptographicOperations.FixedTimeEquals(Encoding.UTF8.GetBytes(a),Encoding.UTF8.GetBytes(b));
 public HttpClient Client(){var client=factory.CreateClient("communications");client.Timeout=TimeSpan.FromSeconds(20);return client;}
 public bool MockAllowed=>env.IsDevelopment()&&config.GetValue<bool>("Communications:AllowTestProvider");
 string MetaBase(JsonObject secrets){var version=secrets["apiVersion"]?.ToString()??"";if(!System.Text.RegularExpressions.Regex.IsMatch(version,@"^v\d+\.\d+$"))throw new DomainException("Configure a supported Meta Graph API version");return "https://graph.facebook.com/"+version;}
 public async Task<bool> Verify(CommunicationAccount a,JsonObject s,CancellationToken ct){if(a.Provider=="Test")return MockAllowed;using var client=Client();HttpRequestMessage request;
 if(a.Provider=="Meta"&&a.Channel=="WhatsApp"){request=new(HttpMethod.Get,MetaBase(s)+"/"+Uri.EscapeDataString(a.ProviderReference)+"?fields=display_phone_number,verified_name");request.Headers.Authorization=new("Bearer",s["token"]?.ToString());}
 else if(a.Provider=="Resend"&&a.Channel=="Email"){request=new(HttpMethod.Get,"https://api.resend.com/domains?limit=100");request.Headers.Authorization=new("Bearer",s["token"]?.ToString());}
 else if(a.Provider=="Twilio"&&a.Channel=="SMS"){request=new(HttpMethod.Get,"https://api.twilio.com/2010-04-01/Accounts/"+Uri.EscapeDataString(a.ProviderReference)+"/IncomingPhoneNumbers.json?PhoneNumber="+Uri.EscapeDataString(a.Sender));request.Headers.Authorization=new("Basic",Convert.ToBase64String(Encoding.UTF8.GetBytes(a.ProviderReference+":"+s["token"])));}
 else if(a.Provider=="Gateway"){var uri=Gateway();request=new(HttpMethod.Get,uri+"/health");request.Headers.Authorization=new("Bearer",s["token"]?.ToString());}
 else return false;
 using var response=await client.SendAsync(request,ct);if(!response.IsSuccessStatusCode)return false;var body=JsonNode.Parse(await response.Content.ReadAsStringAsync(ct))!;
 if(a.Provider=="Resend"){var domain=new System.Net.Mail.MailAddress(a.Sender).Host;return body["data"]?.AsArray().Any(d=>d?["name"]?.ToString()==domain&&d?["status"]?.ToString()=="verified")==true;}
 if(a.Provider=="Twilio")return body["incoming_phone_numbers"]?.AsArray().Any(n=>n?["phone_number"]?.ToString()==a.Sender&&n?["capabilities"]?["sms"]?.GetValue<bool>()==true)==true;
 return a.Provider=="Meta"?!string.IsNullOrWhiteSpace(body["verified_name"]?.ToString()):body["verifiedSender"]?.ToString()==a.Sender;
 }
 string Gateway(){var value=config["Communications:GatewayBaseUrl"]??throw new DomainException("Gateway is not configured by the server operator");if(!Uri.TryCreate(value,UriKind.Absolute,out var uri)||uri.Scheme!="https")throw new DomainException("Gateway requires a server-configured HTTPS URL");return value.TrimEnd('/');}
 public async Task<DispatchResult> Send(Outbox job,CommunicationAccount a,JsonObject s,CancellationToken ct){if(!a.Enabled||!a.Verified)return new("Unavailable",Error:"Sending account is not enabled and verified");if(a.Provider=="Test"){if(!MockAllowed)return new("Failed",Error:"Test provider is disabled");var mode=s["mode"]?.ToString();return mode=="Transient"?new("Retry",Error:"Test rate limit",Retryable:true):mode=="Failure"?new("Failed",Error:"Test provider rejection"):new("Accepted","test-"+job.Id.ToString("N"));}
 var files=job.MessageId==null?new List<MessageAttachment>():await db.Set<MessageAttachment>().Where(f=>f.TenantId==job.TenantId&&f.MessageId==job.MessageId).ToListAsync(ct);
 var attachments=new List<object>();foreach(var file in files){using var input=store.Open(file.TenantId,file.Id);using var output=new MemoryStream();await input.CopyToAsync(output,ct);attachments.Add(new{filename=file.Name,content=Convert.ToBase64String(output.ToArray()),content_type=file.ContentType});}
 using var client=Client();HttpRequestMessage request;
 if(a.Provider=="Resend"&&job.Channel=="Email"){request=new(HttpMethod.Post,"https://api.resend.com/emails");request.Headers.Authorization=new("Bearer",s["token"]?.ToString());request.Headers.Add("Idempotency-Key",job.Id.ToString());request.Content=JsonContent.Create(new{from=a.Sender,to=new[]{job.Recipient},subject=job.Subject,html=CommunityService.Rich(job.Body).Replace("\n","<br>"),attachments,headers=new Dictionary<string,string>{{"X-Entity-Ref-ID",job.Id.ToString()}}});}
 else if(a.Provider=="Meta"&&job.Channel=="WhatsApp"){request=new(HttpMethod.Post,MetaBase(s)+"/"+Uri.EscapeDataString(a.ProviderReference)+"/messages");request.Headers.Authorization=new("Bearer",s["token"]?.ToString());if(files.Count>1)return new("Failed",Error:"WhatsApp supports one attachment per message");if(files.Count==1){var file=files[0];using var upload=new HttpRequestMessage(HttpMethod.Post,MetaBase(s)+"/"+Uri.EscapeDataString(a.ProviderReference)+"/media");upload.Headers.Authorization=new("Bearer",s["token"]?.ToString());using var form=new MultipartFormDataContent();form.Add(new StringContent("whatsapp"),"messaging_product");var stream=new StreamContent(store.Open(file.TenantId,file.Id));stream.Headers.ContentType=new(file.ContentType);form.Add(stream,"file",file.Name);upload.Content=form;using var mediaResponse=await client.SendAsync(upload,ct);if(!mediaResponse.IsSuccessStatusCode)return new("Failed",Error:"Provider rejected media upload");var media=JsonNode.Parse(await mediaResponse.Content.ReadAsStringAsync(ct))?["id"]?.ToString();if(string.IsNullOrEmpty(media))return new("Failed",Error:"Provider returned no media reference");request.Content=file.ContentType=="image/png"?JsonContent.Create(new{messaging_product="whatsapp",to=job.Recipient,type="image",image=new{id=media,caption=job.Body}}):JsonContent.Create(new{messaging_product="whatsapp",to=job.Recipient,type="document",document=new{id=media,filename=file.Name,caption=job.Body}});}else if(job.TemplateName!=null)request.Content=JsonContent.Create(new{messaging_product="whatsapp",to=job.Recipient,type="template",template=new{name=job.TemplateName,language=new{code=job.TemplateLanguage??"en"},components=System.Text.Json.JsonSerializer.Deserialize<string[]>(job.TemplateParameters)!.Length==0?Array.Empty<object>():new object[]{new{type="body",parameters=System.Text.Json.JsonSerializer.Deserialize<string[]>(job.TemplateParameters)!.Select(text=>new{type="text",text})}}}});else{if(job.ConversationId==null)return new("Failed",Error:"WhatsApp requires an approved template outside a verified service window");request.Content=JsonContent.Create(new{messaging_product="whatsapp",to=job.Recipient,type="text",text=new{body=job.Body}});}}
 else if(a.Provider=="Twilio"&&job.Channel=="SMS"){request=new(HttpMethod.Post,"https://api.twilio.com/2010-04-01/Accounts/"+Uri.EscapeDataString(a.ProviderReference)+"/Messages.json");request.Headers.Authorization=new("Basic",Convert.ToBase64String(Encoding.UTF8.GetBytes(a.ProviderReference+":"+s["token"])));var callback=(config["Communications:WebhookBaseUrl"]??config["PublicUrl"])?.TrimEnd('/')+"/api/v1/communications/webhooks/"+a.Id;request.Content=new FormUrlEncodedContent(new Dictionary<string,string>{{"To",job.Recipient},{"From",a.Sender},{"Body",job.Body},{"StatusCallback",callback}});}
 else if(a.Provider=="Gateway"){request=new(HttpMethod.Post,Gateway()+"/messages");request.Headers.Authorization=new("Bearer",s["token"]?.ToString());request.Headers.Add("Idempotency-Key",job.Id.ToString());request.Content=JsonContent.Create(new{reference=job.Id,channel=job.Channel,from=a.Sender,to=job.Recipient,subject=job.Subject,text=job.Body,attachments});}
 else return new("Unavailable",Error:"No compatible provider adapter");
 try{using var response=await client.SendAsync(request,ct);var content=await response.Content.ReadAsStringAsync(ct);if((int)response.StatusCode==429)return new("Retry",Error:"Provider rate limit",Retryable:true);if(!response.IsSuccessStatusCode)return new("Failed",Error:"Provider rejected request ("+(int)response.StatusCode+")");var body=JsonNode.Parse(content)!;var id=body["id"]?.ToString()??body["sid"]?.ToString()??body["messages"]?[0]?["id"]?.ToString();return string.IsNullOrEmpty(id)?new("Unknown",Error:"Provider response did not include a reference"):new("Accepted",id);}catch(Exception e)when(e is HttpRequestException or TaskCanceledException){return new("Unknown",Error:"Transport outcome is uncertain; reconcile before retrying");}
 }
}
